components.css:
.ds-ratings {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  width: min(100%, 640px);
}
.ds-rating {
  display: flex;
  flex-direction: column;
  text-align: left;
  padding: 10px 12px;
  min-height: 76px;
  border: 1px solid #d9e2d8;
  border-radius: 8px;
  background: #fff;
}
.ds-rating > span:first-child {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 5px;
  font-size: 13.95px;
}
.ds-rating b {
  font-weight: 600;
}
.ds-rating small {
  font-size: 10.649999999999999px;
  color: var(--muted,#53685b);
  margin-top: 3px;
  white-space: nowrap;
}
.ds-rating kbd {
  font-family: inherit;
  color: #5e7063;
  font-size: 10.200000000000001px;
}
.ds-rating .ds-interval {
  font-size: 11.700000000000001px;
  color: #52674f;
  margin-top: 4px;
}
.ds-rating:hover:not(:disabled) {
  background: #f0f5ed;
  border-color: #7e9e7b;
}
.ds-again:hover:not(:disabled) {
  background: #fff1ed;
  border-color: #cc8b7b;
}
.ds-good {
  background: #edf4e9;
  border-color: #bbcfb0;
}
.ds-rating{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#283c34;cursor:pointer;transition:background-color .16s,color .16s,border-color .16s;}.ds-rating:focus-visible{outline:3px solid #477451;outline-offset:3px;}.ds-rating:disabled{opacity:.5;cursor:not-allowed;}@media(max-width:800px){.ds-ratings{grid-template-columns:repeat(2,1fr);gap:8px;}}@media(max-width:600px){.ds-rating b{font-size:13.95px;}.ds-rating small{font-size:10.5px;}}@media(prefers-reduced-motion:reduce){.ds-rating{transition:none;}}
